mapper.sql:
FROM distribution_product dp JOIN goods_main gm ON gm.goods_id = dp.goods_id AND gm.camp_id = dp.camp_id AND gm.is_deleted = 0 JOIN goods_room_category_rel grr ON grr.goods_id = gm.goods_id JOIN room_category rc ON rc.room_category_id = grr.room_category_id AND rc.camp_id = gm.camp_id AND rc.status = 1 AND rc.is_deleted = 0 JOIN ( SELECT rel.camp_id AS camp_id, rel.room_category_id AS room_category_id, ca.channel_id AS channel_id, ca.channel_name AS channel_name, MIN(ca.account_id) AS sort_account_id FROM channel_room_category_rel rel JOIN channel_account ca ON ca.account_id = rel.account_id AND ca.camp_id = rel.camp_id WHERE ca.status = 'authorized' AND rel.shelf_status = 'on_shelf' AND rel.audit_status = 'approved' GROUP BY rel.camp_id, rel.room_category_id, ca.channel_id, ca.channel_name ) cb ON cb.camp_id = gm.camp_id AND cb.room_category_id = rc.room_category_id WHERE gm.camp_id = #{campId} AND dp.status = 1
AND ( gm.name LIKE CONCAT('%', #{keyword}, '%') OR rc.name LIKE CONCAT('%', #{keyword}, '%') )
AND rc.room_category_id = #{roomCategoryId}
AND cb.channel_id = #{channelId}
